def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    last_m, last_o = history[-1]
    opp_defects = sum(1 for _, o in history if o == 'D')
    if last_o == 'C':
        return 'C'
    if n == 1:
        return 'C'
    if n < 10:
        return 'D'
    if opp_defects <= 1:
        return 'C'
    if opp_defects <= n // 10:
        return 'C'
    if opp_defects > 0.5 * n:
        return 'D'
    if last_m == 'C':
        if n >= 3 and history[-2][0] == 'D' and history[-2][1] == 'D':
            return 'C'
        return 'D'
    count = 0
    for i in reversed(history):
        if i[0] == 'D' and i[1] == 'D':
            count += 1
        else:
            break
    if count >= 4:
        return 'C'
    return 'D'
